    { key = "StormWind", page = 5, kind = "float", min = 0, max = 20, default = "7", label = L["Storm wind"], tip = L["Drift speed in yards per second in clear weather (0-10), and in full rain, snow or sandstorm (0-20); weaker weather lies in between"] },
    { key = "WindDirection", page = 5, kind = "float", min = 0, max = 360, default = "60", label = L["Wind direction"], tip = L["Where the wind blows to, in degrees: 0 north, 90 east, 180 south, 270 west"] },
    { key = "MorningMist", page = 5, kind = "float", min = 0, max = 8, default = "2.0", label = L["Morning mist"], tip = L["Morning mist in low ground: extra fog near and below your ground level at dawn (full 05:00 to 07:30, gone by 10:00). 2 = three times the fog near the ground (0-8); a zone with little fog of its own near the ground gets up to eight times more, so the mist shows there too. MistHeight is how far above your ground level it reaches, in yards (2-60)"] },
    { key = "MistHeight", page = 5, kind = "float", min = 2, max = 60, default = "12", label = L["Mist height"], tip = L["Morning mist in low ground: extra fog near and below your ground level at dawn (full 05:00 to 07:30, gone by 10:00). 2 = three times the fog near the ground (0-8); a zone with little fog of its own near the ground gets up to eight times more, so the mist shows there too. MistHeight is how far above your ground level it reaches, in yards (2-60)"] },
    { key = "EveningHaze", page = 5, kind = "float", min = 0, max = 2, default = "0.4", label = L["Evening haze"], tip = L["Evening haze: extra fog everywhere in the evening (full 20:00 to 22:00, gone by midnight). 0.4 = 40% more (0-2)"] },
    { key = "WeatherFog", page = 5, kind = "float", min = 0, max = 4, default = "0.25", label = L["Weather fog"], tip = L["Weather: extra fog in full rain, snow or sandstorm (1 = twice the fog, 0-4), the share of the shafts left as clouds hide the sun (0-1), how far the fog turns grey in rain, white in snow and sandy in a sandstorm (0-1), and how far the sky and its clouds turn the colour of that fog, an overcast sky (0-1, 1 = 85% in full weather)"] },
    { key = "WeatherShafts", page = 5, kind = "float", min = 0, max = 1, default = "0.35", label = L["Weather shafts"], tip = L["Weather: extra fog in full rain, snow or sandstorm (1 = twice the fog, 0-4), the share of the shafts left as clouds hide the sun (0-1), how far the fog turns grey in rain, white in snow and sandy in a sandstorm (0-1), and how far the sky and its clouds turn the colour of that fog, an overcast sky (0-1, 1 = 85% in full weather)"] },
    { key = "WeatherTint", page = 5, kind = "float", min = 0, max = 1, default = "1.0", label = L["Weather tint"], tip = L["Weather: extra fog in full rain, snow or sandstorm (1 = twice the fog, 0-4), the share of the shafts left as clouds hide the sun (0-1), how far the fog turns grey in rain, white in snow and sandy in a sandstorm (0-1), and how far the sky and its clouds turn the colour of that fog, an overcast sky (0-1, 1 = 85% in full weather)"] },
    { key = "WeatherSky", page = 5, kind = "float", min = 0, max = 1, default = "1.0", label = L["Weather sky"], tip = L["Weather: extra fog in full rain, snow or sandstorm (1 = twice the fog, 0-4), the share of the shafts left as clouds hide the sun (0-1), how far the fog turns grey in rain, white in snow and sandy in a sandstorm (0-1), and how far the sky and its clouds turn the colour of that fog, an overcast sky (0-1, 1 = 85% in full weather)"] },
    { key = "RainInFront", page = 5, kind = "float", min = 0, max = 1, default = "1.0", label = L["Rain in front"], tip = L["Rain, snow and sand drawn by the client stay in front of the fog and the overcast sky (1 = fogged as if 25 yd away, 0 = as if as far as what is behind them, 0-1)"] },
    { key = "Twilight", page = 5, kind = "float", min = 0, max = 2, default = "1.0", label = L["Twilight"], tip = L["Blue tint of the fog around sunset and sunrise, while the sun is just below the horizon (0-2)"] },
    { key = "SkyboxMoons", page = 5, kind = "bool", default = "0", label = L["Skybox moons"], tip = L["The moons the HD skyboxes paint on their sky (Arathi, Feralas, Kalimdor's tundra skies and more): 0 = left out, so only the game's own moon shows, the one the moonlight, the moon shafts and the glitter on the water come from; 1 = drawn as well"] },
    { key = "SunAndMoon", page = 5, kind = "float", min = 0, max = 1, default = "1.0", label = L["Sun and moon"], tip = L["The game's own sun and moon drawn over the sky last, so an HD skybox or the sky haze cannot hide them; land in front still does (1 = as the client draws them, dimmer in thick fog and rain; 0 = left to the client; needs ColorSpace=1)"] },
    { key = "LightGlow", page = 6, kind = "float", min = 0, max = 8, default = "0", label = L["Light glow"], tip = L["Lamps, windows and fires glow into the fog at night; the thicker the fog, the larger the halo (0-8, 0 = off). GlowThreshold is how bright a pixel must be to glow (0.2-0.95; lower = more things glow)"] },
    { key = "GlowThreshold", page = 6, kind = "float", min = 0.2, max = 0.95, default = "0.4", label = L["Glow threshold"], tip = L["Lamps, windows and fires glow into the fog at night; the thicker the fog, the larger the halo (0-8, 0 = off). GlowThreshold is how bright a pixel must be to glow (0.2-0.95; lower = more things glow)"] },
    { key = "LampFog", page = 6, kind = "float", min = 0, max = 4, default = "0.17", label = L["Lamp fog"], tip = L["Lamp halos: torches, candles, braziers, campfires, lanterns and street lamps placed in the world glow in the air, from the lamp list lampdata.bin next to the DLL (tools/lamp_extract). By day the LampDayLight share, more in rain, snow or sand and in thicker fog or morning mist, none in the ghost world (0-4, 0 = off). LampCount is how many of the lamps in view are used, those giving the most light at the camera first (0-128), LampFlicker how much flames flicker (0-2, 0 = steady; lanterns behind glass never flicker), FireStrength the strength of open fires (braziers, bonfires, campfires, hearths), their light and halos, against the other lamps (0-2, 1 = the same), LampIndoors the strength of lamps inside rooms, and of every lamp while the player stands indoors, their light and halos (0-2, 1 = as outdoors). FarLights: at night the outdoor lamps from 60 yd out also show as small points of light, even where their halos are too faint to see, so a town across a valley isn't dark (0-4, 0 = off)"] },
    { key = "LampCount", page = 6, kind = "int", min = 0, max = 128, default = "110", label = L["Lamp count"], tip = L["Lamp halos: torches, candles, braziers, campfires, lanterns and street lamps placed in the world glow in the air, from the lamp list lampdata.bin next to the DLL (tools/lamp_extract). By day the LampDayLight share, more in rain, snow or sand and in thicker fog or morning mist, none in the ghost world (0-4, 0 = off). LampCount is how many of the lamps in view are used, those giving the most light at the camera first (0-128), LampFlicker how much flames flicker (0-2, 0 = steady; lanterns behind glass never flicker), FireStrength the strength of open fires (braziers, bonfires, campfires, hearths), their light and halos, against the other lamps (0-2, 1 = the same), LampIndoors the strength of lamps inside rooms, and of every lamp while the player stands indoors, their light and halos (0-2, 1 = as outdoors). FarLights: at night the outdoor lamps from 60 yd out also show as small points of light, even where their halos are too faint to see, so a town across a valley isn't dark (0-4, 0 = off)"] },
    { key = "LampFlicker", page = 6, kind = "float", min = 0, max = 2, default = "1.0", label = L["Lamp flicker"], tip = L["Lamp halos: torches, candles, braziers, campfires, lanterns and street lamps placed in the world glow in the air, from the lamp list lampdata.bin next to the DLL (tools/lamp_extract). By day the LampDayLight share, more in rain, snow or sand and in thicker fog or morning mist, none in the ghost world (0-4, 0 = off). LampCount is how many of the lamps in view are used, those giving the most light at the camera first (0-128), LampFlicker how much flames flicker (0-2, 0 = steady; lanterns behind glass never flicker), FireStrength the strength of open fires (braziers, bonfires, campfires, hearths), their light and halos, against the other lamps (0-2, 1 = the same), LampIndoors the strength of lamps inside rooms, and of every lamp while the player stands indoors, their light and halos (0-2, 1 = as outdoors). FarLights: at night the outdoor lamps from 60 yd out also show as small points of light, even where their halos are too faint to see, so a town across a valley isn't dark (0-4, 0 = off)"] },
    { key = "FireStrength", page = 6, kind = "float", min = 0, max = 2, default = "0.5625", label = L["Fire strength"], tip = L["Lamp halos: torches, candles, braziers, campfires, lanterns and street lamps placed in the world glow in the air, from the lamp list lampdata.bin next to the DLL (tools/lamp_extract). By day the LampDayLight share, more in rain, snow or sand and in thicker fog or morning mist, none in the ghost world (0-4, 0 = off). LampCount is how many of the lamps in view are used, those giving the most light at the camera first (0-128), LampFlicker how much flames flicker (0-2, 0 = steady; lanterns behind glass never flicker), FireStrength the strength of open fires (braziers, bonfires, campfires, hearths), their light and halos, against the other lamps (0-2, 1 = the same), LampIndoors the strength of lamps inside rooms, and of every lamp while the player stands indoors, their light and halos (0-2, 1 = as outdoors). FarLights: at night the outdoor lamps from 60 yd out also show as small points of light, even where their halos are too faint to see, so a town across a valley isn't dark (0-4, 0 = off)"] },
    { key = "LampIndoors", page = 6, kind = "float", min = 0, max = 2, default = "0.49", label = L["Lamp indoors"], tip = L["Lamp halos: torches, candles, braziers, campfires, lanterns and street lamps placed in the world glow in the air, from the lamp list lampdata.bin next to the DLL (tools/lamp_extract). By day the LampDayLight share, more in rain, snow or sand and in thicker fog or morning mist, none in the ghost world (0-4, 0 = off). LampCount is how many of the lamps in view are used, those giving the most light at the camera first (0-128), LampFlicker how much flames flicker (0-2, 0 = steady; lanterns behind glass never flicker), FireStrength the strength of open fires (braziers, bonfires, campfires, hearths), their light and halos, against the other lamps (0-2, 1 = the same), LampIndoors the strength of lamps inside rooms, and of every lamp while the player stands indoors, their light and halos (0-2, 1 = as outdoors). FarLights: at night the outdoor lamps from 60 yd out also show as small points of light, even where their halos are too faint to see, so a town across a valley isn't dark (0-4, 0 = off)"] },
    { key = "FarLights", page = 6, kind = "float", min = 0, max = 4, default = "1.0", label = L["Far lights"], tip = L["Lamp halos: torches, candles, braziers, campfires, lanterns and street lamps placed in the world glow in the air, from the lamp list lampdata.bin next to the DLL (tools/lamp_extract). By day the LampDayLight share, more in rain, snow or sand and in thicker fog or morning mist, none in the ghost world (0-4, 0 = off). LampCount is how many of the lamps in view are used, those giving the most light at the camera first (0-128), LampFlicker how much flames flicker (0-2, 0 = steady; lanterns behind glass never flicker), FireStrength the strength of open fires (braziers, bonfires, campfires, hearths), their light and halos, against the other lamps (0-2, 1 = the same), LampIndoors the strength of lamps inside rooms, and of every lamp while the player stands indoors, their light and halos (0-2, 1 = as outdoors). FarLights: at night the outdoor lamps from 60 yd out also show as small points of light, even where their halos are too faint to see, so a town across a valley isn't dark (0-4, 0 = off)"] },
    { key = "LampLight", page = 6, kind = "float", min = 0, max = 4, default = "4", label = L["Lamp light"], tip = L["Lamp light: the same lamps light the ground, walls, plants and characters around them in their own colour, falling off like the game's own point lights, by night and by day, not in the ghost world (0-4, 0 = off). LampDayLight: the share of their light and halos by day, when the sun outshines them (0-1, 0 = none by day, 1 = as at night). LampShadows: things on screen between a lamp and a surface block its light (0-1, 0 = no lamp shadows)"] },
    { key = "LampDayLight", page = 6, kind = "float", min = 0, max = 1, default = "0.11", label = L["Lamp day light"], tip = L["Lamp light: the same lamps light the ground, walls, plants and characters around them in their own colour, falling off like the game's own point lights, by night and by day, not in the ghost world (0-4, 0 = off). LampDayLight: the share of their light and halos by day, when the sun outshines them (0-1, 0 = none by day, 1 = as at night). LampShadows: things on screen between a lamp and a surface block its light (0-1, 0 = no lamp shadows)"] },
    { key = "LampShadows", page = 6, kind = "float", min = 0, max = 1, default = "0.96", label = L["Lamp shadows"], tip = L["Lamp light: the same lamps light the ground, walls, plants and characters around them in their own colour, falling off like the game's own point lights, by night and by day, not in the ghost world (0-4, 0 = off). LampDayLight: the share of their light and halos by day, when the sun outshines them (0-1, 0 = none by day, 1 = as at night). LampShadows: things on screen between a lamp and a surface block its light (0-1, 0 = no lamp shadows)"] },
    { key = "CarriedShadows", page = 6, kind = "float", min = 0, max = 1, default = "0.0", label = L["Carried shadows"], tip = L["Carried light shadows: how much of LampShadows the lights that move with things keep: spells, projectiles, enchants, the loot sparkle and the belt lantern (0-1, 0 = they cast no shadows, so no character's shadow swings around with them; placed lamps keep theirs)"] },
    { key = "WindowLight", page = 6, kind = "float", min = 0, max = 4, default = "2.63", label = L["Window light"], tip = L["Window light: lit windows cast their light onto the street, walls and characters in front of them (up to 8 windows in view, from lampdata.bin), at night only and not in the ghost world (0-4, 0 = off)"] },
    { key = "EffectLight", page = 6, kind = "float", min = 0, max = 4, default = "1.68", label = L["Effect light"], tip = L["Spell light: glowing spells, projectiles, enchants and other bright effects the client draws over the world light the ground, walls and characters around them in their own colour, up to 6 at a time, with lamp shadows. Only what is on screen counts; the flames of the lamps in lampdata.bin are left to the lamps. In rain or snow only coloured glows count. By day the LampDayLight share, not in the ghost world (0-4, 0 = off)"] },
    { key = "CorpseLight", page = 6, kind = "float", min = 0, max = 2, default = "1.0", label = L["Corpse light"], tip = L["Loot sparkle: corpses you can loot give a small golden twinkle of light (the nearest 4 within 40 yd), taken from the client's list of objects, not from the screen. They share the spell light's 6 places, spells first. By day the LampDayLight share, not in the ghost world (0-2, 0 = off)"] },
    { key = "NightDarkness", page = 6, kind = "float", min = 0, max = 0.9, default = "0.75", label = L["Night darkness"], tip = L["Night darkness: darkens the moonlit scene at night outdoors, but not flames, lit windows, lit rooms or what the lamps light, and not while the player is indoors (0-0.9 of the light taken away, 0 = the game's own night)"] },
    { key = "Lantern", page = 6, kind = "int", min = 0, max = 2, default = "0", label = L["Lantern"], tip = L["Belt lantern: a lantern at the player's belt lights the ground, walls, plants and characters around them, and what stands in its light casts shadows (LampShadows). 0 = off; 1 = in the dark: it lights by itself at night and indoors (caves, dungeons, buildings) and goes out by day; 2 = always. Never while swimming or as a ghost. Needs the client's player position (see CoAVolFog.log). LanternKey switches it on or off and saves Lantern here (the key needs Overlay=1)"] },
    { key = "LanternLight", page = 6, kind = "float", min = 0, max = 4, default = "2.96", label = L["Lantern light"], tip = L["Lantern light: how brightly it lights things around the player, in the colour of the game's torches and fires (0-4, 0 = no lantern). Lantern halo: how strongly it glows in the fog around it, times LampFog (0-2, 0 = no glow). Lantern swing: how much it swings on its hook when the player walks, runs, turns and stops (0-2, 0 = it hangs still)"] },
    { key = "LanternHalo", page = 6, kind = "float", min = 0, max = 2, default = "0.3", label = L["Lantern halo"], tip = L["Lantern light: how brightly it lights things around the player, in the colour of the game's torches and fires (0-4, 0 = no lantern). Lantern halo: how strongly it glows in the fog around it, times LampFog (0-2, 0 = no glow). Lantern swing: how much it swings on its hook when the player walks, runs, turns and stops (0-2, 0 = it hangs still)"] },
    { key = "LanternSwing", page = 6, kind = "float", min = 0, max = 2, default = "0.37", label = L["Lantern swing"], tip = L["Lantern light: how brightly it lights things around the player, in the colour of the game's torches and fires (0-4, 0 = no lantern). Lantern halo: how strongly it glows in the fog around it, times LampFog (0-2, 0 = no glow). Lantern swing: how much it swings on its hook when the player walks, runs, turns and stops (0-2, 0 = it hangs still)"] },
    { key = "LanternKey", page = 6, kind = "text", default = "Ctrl+F6", label = L["Lantern key"], tip = L["Lantern light: how brightly it lights things around the player, in the colour of the game's torches and fires (0-4, 0 = no lantern). Lantern halo: how strongly it glows in the fog around it, times LampFog (0-2, 0 = no glow). Lantern swing: how much it swings on its hook when the player walks, runs, turns and stops (0-2, 0 = it hangs still)"] },
    { key = "SpotKey", page = 6, kind = "text", default = "Ctrl+F5", label = L["Spot key"], tip = L["Spot key: saves the place, camera, game time, weather and these settings as a numbered spot in CoAVolFog-spots.txt next to this file, with a copy of the settings in CoAVolFog-spots\\spot-NNN.ini, and shows \"Spot N saved\" for 3 s (the key needs Overlay=1)"] },
    { key = "GodRays", page = 6, kind = "float", min = 0, max = 4, default = "0", label = L["God rays"], tip = L["Radial god rays from the bright sky around the sun, 0 = off (the client's glow already brightens the sun)"] },
    { key = "GlowCompensation", page = 6, kind = "bool", default = "1", label = L["Glow compensation"], tip = L["1 = pre-compensate the fog for the client's full-screen glow (ffxGlow), which otherwise bleaches bright fog around the sun to white; 0 = off"] },
    { key = "FarClipMax", page = 7, kind = "float", min = 0, max = 1583.33, default = "1583.33", label = L["Far clip max"], tip = L["View distance in yards on the continents (Eastern Kingdoms, Kalimdor, Outland, Northrend), which the client caps at 791. Up to 1583 (the engine's limit, used in instances), within the client's own farclip setting. 0 = leave the client's cap. Turning it on when it was 0 at start-up needs a client restart; other changes, including 0, apply at the next farclip change, map load or zone change (e.g. \"/console farclip 1583\"), and raising it shows a loading screen at that moment. Costs about four times the loaded terrain."] },
    { key = "MaxDistance", page = 7, kind = "float", min = 200, max = 5000, default = "5000", label = L["Max distance"], tip = L["Fog range in yards: how far sky rays are integrated and the scale of the Classic distance curves"] },
    { key = "Temporal", page = 7, kind = "float", min = 0, max = 0.97, default = "0.63", label = L["Temporal"], tip = L["History weight of the temporal filter, 0 = off"] },
    { key = "Underwater", page = 7, kind = "bool", default = "0", label = L["Underwater"], tip = L["Keep the effect while the camera is under water"] },
    { key = "LiquidDepth", page = 7, kind = "bool", default = "1", label = L["Liquid depth"], tip = L["Let water surfaces write depth so water is fogged by its own distance"] },
    { key = "WaterReflect", page = 7, kind = "float", min = 0, max = 2, default = "1.04", label = L["Water reflect"], tip = L["Water (needs LiquidDepth=1; lava and slime stay as the game draws them). Reflections of the sky, shores, trees and buildings on screen: strong when you look across the water, weak when you look down into it. 0-2, 0 = off"] },
    { key = "WaterGlitter", page = 7, kind = "float", min = 0, max = 4, default = "1.99", label = L["Water glitter"], tip = L["Sparkling path of the sun, and of the moon at night, on the waves (less under clouds), and the glints of lamps and lit windows on the water; none in the ghost world. 0-4, 0 = off"] },
    { key = "WaterClarity", page = 7, kind = "float", min = 0, max = 1, default = "0.5", label = L["Water clarity"], tip = L["See the bottom through shallow water, and a deeper teal where the water gets deep. 0-1, 0 = the game's own water colour"] },
    { key = "WaterWaves", page = 7, kind = "float", min = 0, max = 2, default = "0.25", label = L["Water waves"], tip = L["Small waves that break up the reflections and the glitter, higher in rain, snow or sand, and the ripples around your feet while you wade or swim. 0-2, 0 = a still mirror"] },
    { key = "WaterRain", page = 7, kind = "float", min = 0, max = 2, default = "1", label = L["Water rain"], tip = L["How strongly raindrops ring out on the water while it rains; how many follows the rain. None in snow or sand. Far away the rings roughen the water instead. 0-2, 0 = off"] },
    { key = "WaterMemory", page = 7, kind = "bool", default = "1", label = L["Water memory"], tip = L["Reflections of what left the screen come from a panorama of everything seen from here, so turning the camera does not make them pop or vanish. 0 = only what is on screen"] },
    { key = "SurfaceSheen", page = 8, kind = "float", min = 0, max = 2, default = "1", label = L["Surface sheen"], tip = L["Wet and shiny surfaces (only with ColorSpace=1; none in the ghost world or indoors). Stone, cobbles, rock, ice and other smooth surfaces catch the sun, the moon and the lamps when you look along them toward the light, most of all under a low sun; snow sparkles; grass, dirt and sand stay matt. 0-2, 0 = off"] },
    { key = "WetSurfaces", page = 8, kind = "float", min = 0, max = 2, default = "0", label = L["Wet surfaces"], tip = L["Rain wets what stands under the open sky within about a minute, each ground as its material takes water: stone gets a glossy film at once, soil and sand darken first and gloss only once soaked, grass beads into droplets that glint but never mirror, snow does not darken. Wet surfaces reflect the sky, what is on screen and the lamps. It dries over minutes once the rain stops, slower at night. Nothing under roofs. 0-2, 0 = surfaces never get wet"] },
    { key = "Puddles", page = 8, kind = "float", min = 0, max = 2, default = "0", label = L["Puddles"], tip = L["How much of the flat open ground pools into puddles in steady rain: still mirrors of the sky, the land and the lamps that fill over a minute or two and outlast the wet ground. Water stands on stone, soil and ice, hardly on sand, never on grass or snow. 0-2, 0 = no puddles"] },
    { key = "TerrainMaterials", page = 8, kind = "bool", default = "1", label = L["Terrain materials"], tip = L["Tell what a surface is made of from its texture, so rain wets each the way it should (only with the game's shadows at extShadowQuality 3 or more): the ground from materialdata.bin next to this file (grass, soil, stone, sand, snow, ice, wood or lava), buildings and models from their relief type (stone, wood, metal, fabric, ...; models need ReliefModels=1). 0 = judge every surface by its colour"] },
    { key = "Relief", page = 8, kind = "bool", default = "1", label = L["Relief"], tip = L["Ground relief: cobbles, rocks, roads and dirt on the terrain get depth from a height map per texture (reliefdata.bin next to this file): stones stand up, hide what lies behind them, catch the sun on one side and cast small shadows. Only with the game's shadows at extShadowQuality 3 or more. ReliefKey switches it on or off and saves Relief here (the key needs Overlay=1)"] },
    { key = "ReliefModels", page = 8, kind = "bool", default = "0", label = L["Relief models"], tip = L["Relief on models: trees, creatures, characters, armour and props get relief too. Their height maps are made while the game runs, on a thread of their own, the first time each texture is drawn (0 = buildings and ground only)"] },
    { key = "ReliefDepth", page = 8, kind = "float", min = 0, max = 0.75, default = "0.138", label = L["Relief depth"], tip = L["Relief depth: how deep the deepest cracks are, in yards, for cobbles and rocks; every other type of texture gets its own share of it below (0-0.75, 0 = flat)"] },
    { key = "ReliefLight", page = 8, kind = "float", min = 0, max = 2, default = "1.01", label = L["Relief light"], tip = L["Relief light: how much the relief's own slopes brighten and darken in the sun (0-2, 0 = the ground's own light). Relief shadows: how dark the small shadows inside the relief are (0-1, 0 = none)"] },
    { key = "ReliefShadows", page = 8, kind = "float", min = 0, max = 1, default = "1.0", label = L["Relief shadows"], tip = L["Relief light: how much the relief's own slopes brighten and darken in the sun (0-2, 0 = the ground's own light). Relief shadows: how dark the small shadows inside the relief are (0-1, 0 = none)"] },
    { key = "ReliefDistance", page = 8, kind = "float", min = 5, max = 1500, default = "161", label = L["Relief distance"], tip = L["Relief distance: how far from the camera the ground keeps its relief, in yards; it fades out over the last quarter of it (5-1500)"] },
    { key = "ReliefRoads", page = 8, kind = "float", min = 0, max = 3, default = "0.4", label = L["Relief roads"], tip = L["Relief by texture type: each type's share of the relief depth (0-3; 0 = flat, 1 = the full depth). A texture that is smooth in itself, such as plain snow or a solid colour, gets less whatever its type. The ground, buildings and, with ReliefModels=1, models have relief Roads, paving, cobbles and paved floors, outdoors and in buildings"] },
    { key = "ReliefRock", page = 8, kind = "float", min = 0, max = 3, default = "0.4", label = L["Relief rock"], tip = L["Rock, cliffs, gravel, boulders and caves"] },
    { key = "ReliefDirt", page = 8, kind = "float", min = 0, max = 3, default = "1.1", label = L["Relief dirt"], tip = L["Dirt, mud, soil, ash, and ground of no other type"] },
